if cfg.Timeout > 0 {
	// With timeout
	select {
	case err = <-channel:
	case <-time.After(cfg.Timeout):
		conn.Close() //nolint:errcheck, revive // It is fine to ignore the error here
		if cfg.FailOnTimeout {
			return nil, os.ErrDeadlineExceeded
