    let rx = new_watch(()).map_err(Box::new)?.1;
    rx.has_changed().map_err(Box::new)?;
    Ok(())
}

async fn drop_sender_then_changed() -> Result<(), Box<dyn Error>> {
    let mut rx = new_watch(()).map_err(Box::new)?.1;
    rx.changed().await.map_err(Box::new)?;
    Ok(())
