### Workaround

At the very beginning of my app, I replaced the implementation of `Headers`:
```typescript
import { HeadersInit } from 'undici-types';

{
  const base = Headers;

  class CustomHeadersImpl extends base {
    constructor(init: HeadersInit) {
      const entries = Object.entries(init)
        .filter(entry => !entry[0].startsWith(':'));

      super(Object.fromEntries(entries));
    }
  }

  Headers = CustomHeadersImpl;
}
```

